/**
 * Every tunable number in the pipeline. One file so Phase 2 retuning is a
 * single reviewable diff, and so the eval harness and the workflow can never
 * disagree about the threshold.
 */

/** Scores at or above this get a Slack card. Below, the job is logged and dropped. */
const SCORE_THRESHOLD = 70;

/** Slack Send-and-Wait timeout. A Friday-night post must survive the weekend. */
const APPROVAL_TIMEOUT_HOURS = 72;

/** WF3 fires if fewer than this many jobs were seen in the last 24h. */
const MIN_JOBS_PER_DAY = 1;

/** Draft length gate, enforced by the draft eval and stated in the prompt. */
const DRAFT_MIN_WORDS = 120;
const DRAFT_MAX_WORDS = 350;

/** Model choices. Scoring is high-volume and mechanical; drafting is not. */
const SCORING_MODEL = 'claude-haiku-4-5';
const DRAFTING_MODEL = 'claude-sonnet-5';

/** Drafting effort. Sonnet 5 accepts low|medium|high|xhigh|max. */
const DRAFT_EFFORT = 'low';

/**
 * Scoring response mode. 'structured' uses output_config.format; 'tool' uses a
 * strict tool with forced tool_choice. Settle this with scripts/check-json-mode.mjs
 * before wiring the workflow - it is a live-API fact, not a guess.
 */
const SCORING_JSON_MODE = 'structured';
// ==END INLINED src/thresholds.js==

// ==BEGIN INLINED src/slack-card.js==
/**
 * Render the Slack approval message for a scored job.
 *
 * Kept out of the n8n node's expression field on purpose: message text is the
 * part of this pipeline Dave will fiddle with most, and here it is testable and
 * reviewable in a diff.
 */

function scoreBadge(score) {
  if (score >= 85) return '🟢';
  if (score >= 70) return '🟡';
  return '🔴';
}

/** @returns {string} Slack mrkdwn */
function renderJobCard(job, score) {
  const lines = [
    `${scoreBadge(score.score)} *${score.score}/100* · ${score.verdict}`,
    `*<${job.url}|${job.title || 'untitled posting'}>*`,
    `💰 ${job.budget_display}   👤 ${job.client_summary}`,
  ];
  if (job.proposals != null) lines.push(`📊 ${job.proposals} proposals so far`);
  lines.push('', `_${score.reasoning}_`);
  if (score.red_flags && score.red_flags.length) {
    lines.push('', `⚠️ ${score.red_flags.join(' · ')}`);
  }
  return lines.join('\n');
}

/** The draft, posted as a threaded reply so the card stays scannable. */
function renderDraftMessage(job, draft) {
  return [
    `*Draft proposal — ${job.title || 'untitled posting'}*`,
    '',
    '```',
    draft.proposal,
    '```',
    '',
    `💵 ${draft.rate_note}`,
    `🔗 <${job.url}|Open the posting to submit>`,
  ].join('\n');
}

function renderHealthAlert({ jobsLast24h, windowHours = 24 }) {
  return [
    '🚨 *Upwork pipeline may be broken*',
    `No jobs processed in the last ${windowHours}h (count: ${jobsLast24h}).`,
    'Likely causes, in order: IMAP app password rotated or revoked, Vollna alert',
    'template changed so the parser returns nothing, or the Vollna filter itself',
    'stopped emailing. Check the n8n executions list first.',
  ].join('\n');
}
// ==END INLINED src/slack-card.js==

// ---- node logic ----
// Counts WF1 executions in the window via the n8n API. Deliberately not read
// from workflow static data: static data is per-workflow, and an IMAP trigger
// that never fires would leave WF1's state untouched and this check blind.
const since = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
const executions = ($input.first().json.data || []).filter((e) => e.startedAt >= since);
const jobsLast24h = executions.length;

return [{
  json: {
    jobsLast24h,
    unhealthy: jobsLast24h < MIN_JOBS_PER_DAY,
    message: renderHealthAlert({ jobsLast24h }),
  },
}];
